content.content:
1	package shadow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"os"
9		"path/filepath"
10		"sync"
11		"time"
12	)
13	
14	const storeFileName = "shadow-store.json"
15	const storeFormat = 1
16	
17	// View 是设备影子当前状态的只读快照。
18	type View struct {
19		DeviceID string
20		// Version 是设备当前版本（登记时的初始版本，随有效上报更新）。
21		Version string
22		// Online 表示设备是否在线。新登记设备离线，有效上报置为在线。
23		Online bool
24		// Revision 是当前期望配置的修订号，从零开始，每次成功修改加一。
25		Revision uint64
26		// Desired 是期望配置的完整 JSON 对象。
27		Desired json.RawMessage
28		// Reported 是上报配置的完整 JSON 对象。
29		Reported json.RawMessage
30		// LastSeq 是最后接受的上报序号。
31		LastSeq uint64
32	}
33	
34	// AuditRecord 是一次成功修改期望配置的审计记录。
35	type AuditRecord struct {
36		DeviceID string
37		Operator string
38		Time     time.Time
39		// Revision 是本次修改产生的新修订号。
40		Revision uint64
41		// RequestID 是产生本次修改的批量请求标识；单设备修改为空。
42		RequestID string
43		// Before 是修改前的完整期望配置。
44		Before json.RawMessage
45		// After 是修改后的完整期望配置。
46		After json.RawMessage
47	}
48	
49	// deviceState 是单台设备的内部状态。
50	type deviceState struct {
51		Version        string
52		Online         bool
53		Revision       uint64
54		Desired        json.RawMessage
55		Reported       json.RawMessage
56		LastSeq        uint64
57		LastReportTime time.Time
58		// DiffSince 记录每条差异路径首次出现的时间。
59		DiffSince map[string]time.Time
60		Audit     []AuditRecord
61	}
62	
63	// refreshDiff 重新计算差异路径：已有路径保留原时间，新路径使用 t，消失的路径移除。
64	func (d *deviceState) refreshDiff(t time.Time) {
65		entries := computeDiff(d.Desired, d.Reported)
66		next := make(map[string]time.Time, len(entries))
67		for _, e := range entries {
68			if since, ok := d.DiffSince[e.Path]; ok {
69				next[e.Path] = since
70			} else {
71				next[e.Path] = t
72			}
73		}
74		d.DiffSince = next
75	}
76	
77	// Store 是本地设备影子存储，所有状态与审计记录保存在指定目录。
78	// Store 可安全并发使用。
79	type Store struct {
80		mu        sync.Mutex
81		dir       string
82		closed    bool
83		devices   map[string]*deviceState
84		versions  map[string]*versionState
85		campaigns map[string]*campaignState
86		batches   map[string]*batchRequestState
87	}
88	
89	// Open 打开（必要时创建）位于 dir 的本地影子存储。
90	// 已有内容损坏或格式不识别时返回 ErrCorruptStorage，不会按空数据覆盖。
91	func Open(dir string) (*Store, error) {
92		if err := os.MkdirAll(dir, 0o755); err != nil {
93			return nil, fmt.Errorf("shadow: create store dir: %w", err)
94		}
95		s := &Store{
96			dir:       dir,
97			devices:   map[string]*deviceState{},
98			versions:  map[string]*versionState{},
99			campaigns: map[string]*campaignState{},
100			batches:   map[string]*batchRequestState{},
101		}
102		data, err := os.ReadFile(s.filePath())
103		if errors.Is(err, fs.ErrNotExist) {
104			return s, nil
105		}
106		if err != nil {
107			return nil, fmt.Errorf("shadow: read store: %w", err)
108		}
109		if err := s.restore(data); err != nil {
110			return nil, err
111		}
112		return s, nil
113	}
114	
115	// Close 关闭存储。关闭后的操作返回 ErrClosed。
116	func (s *Store) Close() error {
117		s.mu.Lock()
118		defer s.mu.Unlock()
119		if s.closed {
120			return ErrClosed
121		}
122		s.closed = true
123		return nil
124	}
125	
126	// Register 登记一台模拟设备。设备标识和初始版本不能为空；
127	// 重复登记返回 ErrDeviceExists。新设备初始离线，双方配置均为空对象。
128	func (s *Store) Register(deviceID, version string) error {
129		s.mu.Lock()
130		defer s.mu.Unlock()
131		if err := s.checkOpen(); err != nil {
132			return err
133		}
134		if deviceID == "" {
135			return ErrInvalidDeviceID
136		}
137		if version == "" {
138			return ErrInvalidVersion
139		}
140		if _, ok := s.devices[deviceID]; ok {
141			return fmt.Errorf("%w: %s", ErrDeviceExists, deviceID)
142		}
143		return s.commit(func() error {
144			s.devices[deviceID] = &deviceState{
145				Version:   version,
146				Desired:   json.RawMessage(`{}`),
147				Reported:  json.RawMessage(`{}`),
148				DiffSince: map[string]time.Time{},
149			}
150			return nil
151		})
152	}
153	
154	// UpdateDesired 修改设备的期望配置，完整替换旧配置。
155	// 需携带操作者、操作时间和已读取的期望修订号；修订号不等于当前值时
156	// 返回 ErrRevisionConflict，影子和审计均不改变。成功时返回新修订号。
157	func (s *Store) UpdateDesired(deviceID, operator string, at time.Time, revision uint64, config json.RawMessage) (uint64, error) {
158		s.mu.Lock()
159		defer s.mu.Unlock()
160		if err := s.checkOpen(); err != nil {
161			return 0, err
162		}
163		d, err := s.lookup(deviceID)
164		if err != nil {
165			return 0, err
166		}
167		if operator == "" {
168			return 0, ErrInvalidOperator
169		}
170		if at.IsZero() {
171			return 0, ErrInvalidTime
172		}
173		cfg, err := validateConfig(config)
174		if err != nil {
175			return 0, err
176		}
177		if revision != d.Revision {
178			return 0, fmt.Errorf("%w: want %d, got %d", ErrRevisionConflict, d.Revision, revision)
179		}
180		var newRevision uint64
181		err = s.commit(func() error {
182			before := d.Desired
183			d.Desired = cfg
184			d.Revision++
185			newRevision = d.Revision
186			d.Audit = append(d.Audit, AuditRecord{
187				DeviceID: deviceID,
188				Operator: operator,
189				Time:     at,
190				Revision: newRevision,
191				Before:   cloneRaw(before),
192				After:    cloneRaw(cfg),
193			})
194			d.refreshDiff(at)
195			return nil
196		})
197		if err != nil {
198			return 0, err
199		}
200		return newRevision, nil
201	}
202	
203	// Report 处理设备上报。需携带正整数序号、时间、非空当前版本和完整配置。
204	// 更大序号更新上报并标为在线；相同序号且版本、配置、时间相同视为重复，
205	// 成功返回但不改变状态；相同序号内容不同或更小序号返回错误。
206	func (s *Store) Report(deviceID string, seq uint64, at time.Time, version string, config json.RawMessage) error {
207		s.mu.Lock()
208		defer s.mu.Unlock()
209		if err := s.checkOpen(); err != nil {
210			return err
211		}
212		d, err := s.lookup(deviceID)
213		if err != nil {
214			return err
215		}
216		if seq == 0 {
217			return ErrInvalidSequence
218		}
219		if at.IsZero() {
220			return ErrInvalidTime
221		}
222		if version == "" {
223			return ErrInvalidVersion
224		}
225		cfg, err := validateConfig(config)
226		if err != nil {
227			return err
228		}
229		switch {
230		case seq < d.LastSeq:
231			return fmt.Errorf("%w: last accepted %d, got %d", ErrStaleSequence, d.LastSeq, seq)
232		case seq == d.LastSeq:
233			if version == d.Version && at.Equal(d.LastReportTime) && rawEqual(cfg, d.Reported) {
234				return nil // 重复上报：成功返回，不改变状态
235			}
236			return fmt.Errorf("%w: sequence %d", ErrReportConflict, seq)
237		}
238		return s.commit(func() error {
239			d.Reported = cfg
240			d.Version = version
241			d.Online = true
242			d.LastSeq = seq
243			d.LastReportTime = at
244			d.refreshDiff(at)
245			return nil
246		})
247	}
248	
249	// SetOffline 将设备标为离线。只改变在线状态，保留版本及双方配置。
250	func (s *Store) SetOffline(deviceID string) error {
251		s.mu.Lock()
252		defer s.mu.Unlock()
253		if err := s.checkOpen(); err != nil {
254			return err
255		}
256		d, err := s.lookup(deviceID)
257		if err != nil {
258			return err
259		}
260		return s.commit(func() error {
261			d.Online = false
262			return nil
263		})
264	}
265	
266	// Get 返回设备影子当前状态的快照。返回的数据是独立副本，
267	// 调用方修改不影响已保存的记录。
268	func (s *Store) Get(deviceID string) (View, error) {
269		s.mu.Lock()
270		defer s.mu.Unlock()
271		if err := s.checkOpen(); err != nil {
272			return View{}, err
273		}
274		d, err := s.lookup(deviceID)
275		if err != nil {
276			return View{}, err
277		}
278		return View{
279			DeviceID: deviceID,
280			Version:  d.Version,
281			Online:   d.Online,
282			Revision: d.Revision,
283			Desired:  cloneRaw(d.Desired),
284			Reported: cloneRaw(d.Reported),
285			LastSeq:  d.LastSeq,
286		}, nil
287	}
288	
289	// Diff 返回期望配置与上报配置之间的差异，按 JSON Pointer 路径字典序排列。
290	func (s *Store) Diff(deviceID string) ([]DiffEntry, error) {
291		s.mu.Lock()
292		defer s.mu.Unlock()
293		if err := s.checkOpen(); err != nil {
294			return nil, err
295		}
296		d, err := s.lookup(deviceID)
297		if err != nil {
298			return nil, err
299		}
300		entries := computeDiff(d.Desired, d.Reported)
301		for i := range entries {
302			entries[i].Since = d.DiffSince[entries[i].Path]
303		}
304		return entries, nil
305	}
306	
307	// Audit 按修订号递增返回设备的审计记录。返回的数据是独立副本。
308	func (s *Store) Audit(deviceID string) ([]AuditRecord, error) {
309		s.mu.Lock()
310		defer s.mu.Unlock()
311		if err := s.checkOpen(); err != nil {
312			return nil, err
313		}
314		d, err := s.lookup(deviceID)
315		if err != nil {
316			return nil, err
317		}
318		out := make([]AuditRecord, len(d.Audit))
319		for i, rec := range d.Audit {
320			out[i] = rec
321			out[i].Before = cloneRaw(rec.Before)
322			out[i].After = cloneRaw(rec.After)
323		}
324		return out, nil
325	}
326	
327	func (s *Store) checkOpen() error {
328		if s.closed {
329			return ErrClosed
330		}
331		return nil
332	}
333	
334	func (s *Store) lookup(deviceID string) (*deviceState, error) {
335		if deviceID == "" {
336			return nil, ErrInvalidDeviceID
337		}
338		d, ok := s.devices[deviceID]
339		if !ok {
340			return nil, fmt.Errorf("%w: %s", ErrDeviceNotFound, deviceID)
341		}
342		return d, nil
343	}
344	
345	// commit 执行一次状态修改并持久化。保存失败时回滚内存状态并返回错误，
346	// 保证一次操作涉及的状态与审计一起保存、查询仍显示操作前的结果。
347	// 调用时必须持有 s.mu。
348	func (s *Store) commit(mutate func() error) error {
349		snapshot, err := s.marshal()
350		if err != nil {
351			return err
352		}
353		if err := mutate(); err != nil {
354			return err
355		}
356		if err := s.persist(); err != nil {
357			// 回滚内存状态；snapshot 由本进程序列化，恢复不应失败。
358			_ = s.restore(snapshot)
359			return err
360		}
361		return nil
362	}
363	
364	func (s *Store) filePath() string {
365		return filepath.Join(s.dir, storeFileName)
366	}
367	
368	// persist 把当前状态原子写入存储文件。
369	func (s *Store) persist() error {
370		data, err := s.marshal()
371		if err != nil {
372			return err
373		}
374		tmp, err := os.CreateTemp(s.dir, ".shadow-store-*.tmp")
375		if err != nil {
376			return fmt.Errorf("shadow: save store: %w", err)
377		}
378		tmpName := tmp.Name()
379		if _, err := tmp.Write(data); err != nil {
380			tmp.Close()
381			os.Remove(tmpName)
382			return fmt.Errorf("shadow: save store: %w", err)
383		}
384		if err := tmp.Sync(); err != nil {
385			tmp.Close()
386			os.Remove(tmpName)
387			return fmt.Errorf("shadow: save store: %w", err)
388		}
389		if err := tmp.Close(); err != nil {
390			os.Remove(tmpName)
391			return fmt.Errorf("shadow: save store: %w", err)
392		}
393		if err := os.Rename(tmpName, s.filePath()); err != nil {
394			os.Remove(tmpName)
395			return fmt.Errorf("shadow: save store: %w", err)
396		}
397		return nil
398	}
399	
400	// diskStore 是存储文件的磁盘格式。
401	type diskStore struct {
402		Format    int                     `json:"format"`
403		Devices   map[string]diskState    `json:"devices"`
404		Versions  map[string]diskVersion  `json:"versions,omitempty"`
405		Campaigns map[string]diskCampaign `json:"campaigns,omitempty"`
406		Batches   map[string]diskBatch    `json:"batches,omitempty"`
407	}
408	
409	type diskState struct {
410		Version        string               `json:"version"`
411		Online         bool                 `json:"online"`
412		Revision       uint64               `json:"revision"`
413		Desired        json.RawMessage      `json:"desired"`
414		Reported       json.RawMessage      `json:"reported"`
415		LastSeq        uint64               `json:"lastSeq"`
416		LastReportTime time.Time            `json:"lastReportTime,omitempty"`
417		DiffSince      map[string]time.Time `json:"diffSince,omitempty"`
418		Audit          []diskAudit          `json:"audit,omitempty"`
419	}
420	
421	type diskAudit struct {
422		Operator  string          `json:"operator"`
423		Time      time.Time       `json:"time"`
424		Revision  uint64          `json:"revision"`
425		RequestID string          `json:"requestId,omitempty"`
426		Before    json.RawMessage `json:"before"`
427		After     json.RawMessage `json:"after"`
428	}
429	
430	func (s *Store) marshal() ([]byte, error) {
431		disk := diskStore{Format: storeFormat, Devices: make(map[string]diskState, len(s.devices))}
432		for id, d := range s.devices {
433			ds := diskState{
434				Version:        d.Version,
435				Online:         d.Online,
436				Revision:       d.Revision,
437				Desired:        cloneRaw(d.Desired),
438				Reported:       cloneRaw(d.Reported),
439				LastSeq:        d.LastSeq,
440				LastReportTime: d.LastReportTime,
441				DiffSince:      make(map[string]time.Time, len(d.DiffSince)),
442			}
443			for p, t := range d.DiffSince {
444				ds.DiffSince[p] = t
445			}
446			for _, rec := range d.Audit {
447				ds.Audit = append(ds.Audit, diskAudit{
448					Operator:  rec.Operator,
449					Time:      rec.Time,
450					Revision:  rec.Revision,
451					RequestID: rec.RequestID,
452					Before:    cloneRaw(rec.Before),
453					After:     cloneRaw(rec.After),
454				})
455			}
456			disk.Devices[id] = ds
457		}
458		disk.Versions = s.marshalVersions()
459		campaigns, err := s.marshalCampaigns()
460		if err != nil {
461			return nil, err
462		}
463		disk.Campaigns = campaigns
464		disk.Batches = s.marshalBatches()
465		data, err := json.Marshal(disk)
466		if err != nil {
467			return nil, fmt.Errorf("shadow: encode store: %w", err)
468		}
469		return data, nil
470	}
471	
472	// restore 从存储文件内容恢复状态。内容损坏或格式不识别时返回
473	// ErrCorruptStorage，绝不按空数据覆盖。
474	func (s *Store) restore(data []byte) error {
475		var disk diskStore
476		if err := json.Unmarshal(data, &disk); err != nil {
477			return fmt.Errorf("%w: %v", ErrCorruptStorage, err)
478		}
479		if disk.Format != storeFormat {
480			return fmt.Errorf("%w: unsupported format %d", ErrCorruptStorage, disk.Format)
481		}
482		devices := make(map[string]*deviceState, len(disk.Devices))
483		for id, ds := range disk.Devices {
484			if id == "" {
485				return fmt.Errorf("%w: empty device id", ErrCorruptStorage)
486			}
487			if _, ok := decodeObject(ds.Desired); !ok {
488				return fmt.Errorf("%w: device %s desired config invalid", ErrCorruptStorage, id)
489			}
490			if _, ok := decodeObject(ds.Reported); !ok {
491				return fmt.Errorf("%w: device %s reported config invalid", ErrCorruptStorage, id)
492			}
493			d := &deviceState{
494				Version:        ds.Version,
495				Online:         ds.Online,
496				Revision:       ds.Revision,
497				Desired:        cloneRaw(ds.Desired),
498				Reported:       cloneRaw(ds.Reported),
499				LastSeq:        ds.LastSeq,
500				LastReportTime: ds.LastReportTime,
501				DiffSince:      make(map[string]time.Time, len(ds.DiffSince)),
502			}
503			for p, t := range ds.DiffSince {
504				d.DiffSince[p] = t
505			}
506			var lastRev uint64
507			for _, da := range ds.Audit {
508				if da.Operator == "" || da.Time.IsZero() || da.Revision == 0 || da.Revision <= lastRev {
509					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
510				}
511				if _, ok := decodeObject(da.Before); !ok {
512					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
513				}
514				if _, ok := decodeObject(da.After); !ok {
515					return fmt.Errorf("%w: device %s audit invalid", ErrCorruptStorage, id)
516				}
517				lastRev = da.Revision
518				d.Audit = append(d.Audit, AuditRecord{
519					DeviceID:  id,
520					Operator:  da.Operator,
521					Time:      da.Time,
522					Revision:  da.Revision,
523					RequestID: da.RequestID,
524					Before:    cloneRaw(da.Before),
525					After:     cloneRaw(da.After),
526				})
527			}
528			devices[id] = d
529		}
530		s.devices = devices
531		if err := s.restoreVersions(disk.Versions); err != nil {
532			return err
533		}
534		if err := s.restoreCampaigns(disk.Campaigns); err != nil {
535			return err
536		}
537		if err := s.restoreBatches(disk.Batches); err != nil {
538			return err
539		}
540		return nil
541	}
