14	func mustBatch(t *testing.T, s *Store, reqID, op string, at time.Time, devices []BatchDevice) BatchRecord {
15		t.Helper()
16		rec, err := s.BatchUpdateDesired(reqID, op, at, devices)
17		if err != nil {
18			t.Fatalf("BatchUpdateDesired(%s): %v", reqID, err)
19		}
20		return rec
