23	func TestBatchUpdateDesiredBasic(t *testing.T) {
24		s, _ := openTemp(t)
25		mustRegister(t, s, "dev-1", "1.0")
26		mustRegister(t, s, "dev-2", "2.0")
27		// dev-2 已有一次单设备修改，修订号从 1 继续
28		if _, err := s.UpdateDesired("dev-2", "op", base, 0, json.RawMessage(`{"x":1}`)); err != nil {
29			t.Fatal(err)
30		}
31	
32		rec := mustBatch(t, s, "req-1", "alice", base, []BatchDevice{
33			{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{"wifi":{"ssid":"a"},"n":1}`)},
34			{DeviceID: "dev-2", Revision: 1, Config: json.RawMessage(`{"x":1}`)}, // 新旧配置相同也加一
35		})
36		if rec.RequestID != "req-1" || rec.Operator != "alice" || !rec.Time.Equal(base) {
37			t.Fatalf("record meta: %+v", rec)
38		}
39		if rec.Revisions["dev-1"] != 1 || rec.Revisions["dev-2"] != 2 || len(rec.Revisions) != 2 {
40			t.Fatalf("revisions: %+v", rec.Revisions)
41		}
42	
43		v1, _ := s.Get("dev-1")
44		if v1.Revision != 1 || string(v1.Desired) != `{"wifi":{"ssid":"a"},"n":1}` {
45			t.Fatalf("dev-1 view: %+v", v1)
46		}
47		v2, _ := s.Get("dev-2")
48		if v2.Revision != 2 || string(v2.Desired) != `{"x":1}` {
49			t.Fatalf("dev-2 view: %+v", v2)
50		}
51		// 批量修改不影响版本、在线状态与上报配置
52		if v1.Version != "1.0" || v1.Online || string(v1.Reported) != "{}" {
53			t.Fatalf("dev-1 side effects: %+v", v1)
54		}
55	
56		// 审计带同一请求标识，仍按修订号顺序查询
57		a1, _ := s.Audit("dev-1")
58		if len(a1) != 1 || a1[0].RequestID != "req-1" || a1[0].Operator != "alice" ||
59			!a1[0].Time.Equal(base) || a1[0].Revision != 1 ||
60			string(a1[0].Before) != `{}` || string(a1[0].After) != `{"wifi":{"ssid":"a"},"n":1}` {
61			t.Fatalf("dev-1 audit: %+v", a1)
62		}
63		a2, _ := s.Audit("dev-2")
64		if len(a2) != 2 || a2[0].RequestID != "" || a2[1].RequestID != "req-1" || a2[1].Revision != 2 {
65			t.Fatalf("dev-2 audit: %+v", a2)
66		}
67	
68		// 差异按现有规则：新增路径使用本次提交时间
69		diffs, _ := s.Diff("dev-1")
70		if len(diffs) != 2 || diffs[0].Path != "/n" || diffs[1].Path != "/wifi" {
71			t.Fatalf("diff: %+v", diffs)
72		}
73		for _, d := range diffs {
74			if !d.Since.Equal(base) {
75				t.Fatalf("diff since: %+v", d)
76			}
77		}
78	
79		// 查询成功提交记录
80		got, err := s.GetBatchRequest("req-1")
81		if err != nil {
82			t.Fatal(err)
83		}
84		if got.Operator != "alice" || !got.Time.Equal(base) ||
85			got.Revisions["dev-1"] != 1 || got.Revisions["dev-2"] != 2 {
86			t.Fatalf("GetBatchRequest: %+v", got)
87		}
88	}
89	
90	func TestBatchValidation(t *testing.T) {
91		s, _ := openTemp(t)
92		mustRegister(t, s, "dev-1", "1.0")
93		mustRegister(t, s, "dev-2", "1.0")
94		good := []BatchDevice{{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{"a":1}`)}}
95	
96		cases := []struct {
97			name    string
98			reqID   string
99			op      string
100			at      time.Time
101			devices []BatchDevice
102			want    error
103		}{
104			{"empty request id", "", "op", base, good, ErrInvalidRequestID},
105			{"empty operator", "r1", "", base, good, ErrInvalidOperator},
106			{"zero time", "r1", "op", time.Time{}, good, ErrInvalidTime},
107			{"empty device list", "r1", "op", base, nil, ErrInvalidDeviceList},
108			{"empty device id", "r1", "op", base, []BatchDevice{{DeviceID: "", Revision: 0, Config: json.RawMessage(`{}`)}}, ErrInvalidDeviceID},
109			{"duplicate device", "r1", "op", base, []BatchDevice{
110				{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{}`)},
111				{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{}`)},
112			}, ErrDuplicateDevice},
113			{"unknown device", "r1", "op", base, []BatchDevice{{DeviceID: "ghost", Revision: 0, Config: json.RawMessage(`{}`)}}, ErrDeviceNotFound},
114			{"bad config", "r1", "op", base, []BatchDevice{{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`[1]`)}}, ErrInvalidConfig},
115			{"revision conflict", "r1", "op", base, []BatchDevice{{DeviceID: "dev-1", Revision: 3, Config: json.RawMessage(`{}`)}}, ErrRevisionConflict},
116		}
117		for _, tc := range cases {
118			if _, err := s.BatchUpdateDesired(tc.reqID, tc.op, tc.at, tc.devices); !errors.Is(err, tc.want) {
119				t.Fatalf("%s: got %v, want %v", tc.name, err, tc.want)
120			}
