151			t.Fatalf("dev-1 modified by failed batch: %+v", v1)
152		}
153		if _, err := s.GetBatchRequest("req-x"); !errors.Is(err, ErrRequestNotFound) {
154			t.Fatalf("failed request queryable: %v", err)
155		}
156		// 同一标识修正后可重新提交
157		if _, err := s.BatchUpdateDesired("req-x", "op", base, []BatchDevice{
158			{DeviceID: "dev-1", Revision: 0, Config: json.RawMessage(`{"a":1}`)},
159			{DeviceID: "dev-2", Revision: 0, Config: json.RawMessage(`{"b":2}`)},
160		}); err != nil {
